// Keep the busy-wait bounded to avoid long blocking in the fuzzer.
// Use a small iteration count (<= 1024) to exercise the code path quickly.
uint32_t count = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024);
spin(count);

// Validation: No inputs/outputs; bounded count prevents hangs and satisfies API allowing any 32-bit value.

// Prepare UART status with random bits to exercise both ready/not-ready paths.
// RXNE is typically bit 5; we just randomize SR and rely on target function logic.
uart->SR = *FUZZ_PARAM(unsigned int);
// Invoke the function under test; it should just read SR and return non-zero if RXNE set.
int ready = uart_read_ready(uart);
// Consume the result in a benign way to avoid optimizing away the call.
if (ready && (uart->SR == 0xFFFFFFFF)) { /* unreachable combo, no-op */ }

// Output: return the same uart object to the pool since it's still valid and owned by the runtime.

// Validation: The stub safely mutates the in-memory struct and calls the function; no blocking/waits or hardware access beyond the provided struct.

// Seed DR with a random byte to read back; SR can be randomized as well.
uart->DR = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0xFFu);
uart->SR = *FUZZ_PARAM(unsigned int);
// Invoke the function under test and read a byte. Reading DR is safe on this in-memory struct.
volatile uint8_t b = uart_read_byte(uart);
// Light use of the value to avoid unused warnings.
if ((b == 0u) && (uart->SR == 0u)) { /* no-op */ }

// Output: return the same uart object to the pool since it's still valid and owned by the runtime.

// Validation: No loops or waits; we only perform plain struct reads/writes compatible with the fuzzer environment.

// Construct a local timer state and parameters. This function is pure logic and does not touch hardware.
// t: persistent state (simulated locally here). Sometimes start from 0 to exercise initialization path.
uint32_t t_state = (*FUZZ_PARAM(unsigned int) % 2) ? 0u : *FUZZ_PARAM(unsigned int);
// prd: allow 0 to cover the immediate-expiration behavior; otherwise keep it moderate.
uint32_t prd = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0x000FFFFFu); // up to ~1M ticks, including 0
// now: random 32-bit counter value.
uint32_t now1 = *FUZZ_PARAM(unsigned int);
// First call exercises either init or regular path.
bool e1 = timer_expired(&t_state, prd, now1);
// Second call advances time by a small delta or near-wrap to exercise wrap-around logic.
uint32_t delta = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0x0000FFFFu); // small positive delta
uint32_t near_wrap_bias = (uint32_t)(*FUZZ_PARAM(unsigned int) % 2);
uint32_t now2 = near_wrap_bias ? (0xFFFFFFFFu - delta) : (now1 + delta);
bool e2 = timer_expired(&t_state, prd, now2);
// Light use of results to avoid unused warnings and keep code paths alive.
if ((int)e1 + (int)e2 == -1) { /* impossible, no-op */ }

// Validation: All parameters are local and bounded; covers init (t=0), prd=0, normal, and near-wrap scenarios without side effects.

// Construct a UART instance as a heap-allocated, fuzzer-managed object.
// No hardware access is performed; we only manipulate the in-memory register block.
struct uart *uart = (struct uart *)malloc(sizeof(struct uart));
if (!uart) { FUZZ_BAIL(); }

// Initialize all registers to deterministic baseline, then apply fuzz/random values
// where safe. This simulates a powered-on, enabled UART that downstream stubs can use.
memset(uart, 0, sizeof(*uart));

// Baud rate register: ensure non-zero to satisfy potential divisions/assumptions.
// Keep value modest; mask to 16 bits and add 1.
uart->BRR = ((uint32_t)(*FUZZ_PARAM(unsigned int) & 0xFFFFu)) + 1u;

// Control register CR1: set UE (bit 13), RE (bit 2), TE (bit 3) to simulate initialized UART.
// Other bits randomized lightly to increase coverage without breaking invariants.
uint32_t cr1_rand = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0x000003FFu); // low misc bits
uart->CR1 = (1u << 13) | (1u << 2) | (1u << 3) | cr1_rand;

// Control registers CR2/CR3 and prescaler GTPR can be fuzzed freely (masked to keep values small).
uart->CR2 = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0x0000FFFFu);
uart->CR3 = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0x0000FFFFu);
uart->GTPR = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0x0000FFFFu);

// Status register SR: set TXE (bit 7) to avoid potential blocking waits in downstream writes.
// Also optionally set RXNE (bit 5) to exercise read-ready paths; rest randomized within 16 bits.
uint32_t sr_rand = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0x0000FFFFu);
uint32_t txe_bit = (1u << 7);
uint32_t rxne_bit = (FUZZ_GET_ATTR_INT_GLOBAL("bias_rxne") ? (1u << 5) : 0u); // optional bias hook
uart->SR = sr_rand | txe_bit | rxne_bit;

// Data register DR: seed with a random byte so uart_read_byte has meaningful content.
uart->DR = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0xFFu);

// Mark attributes so other stubs can verify/use this object safely.
// - initialized: indicates uart is configured and ready for RX/TX in polling mode
// - uart_num: pseudo-identifier 1..3 matching common UART instances
int which = (int)(*FUZZ_PARAM(unsigned int) % 3u) + 1;
FUZZ_SET_ATTR_INT(uart, "initialized", 1);
FUZZ_SET_ATTR_INT(uart, "uart_num", which);

// Property validation: ensure constructed object meets baseline expectations.
FUZZ_ASSERT(uart->BRR != 0u, "UART BRR must be non-zero after construction");
FUZZ_ASSERT((uart->CR1 & (1u << 13)) != 0u, "UART must be enabled (UE)");
FUZZ_ASSERT((uart->CR1 & (1u << 3)) != 0u, "UART TX must be enabled (TE)");
FUZZ_ASSERT((uart->CR1 & (1u << 2)) != 0u, "UART RX must be enabled (RE)");
FUZZ_ASSERT((uart->SR & (1u << 7)) != 0u, "UART TXE should be set to avoid blocking writes");

